package Task_3_1;

public class BankAccount {
    private static int totalAccounts = 0;

    private int accountNumber;
    private double balance;

    public BankAccount(double initialBalance) {
        totalAccounts += 1;
        this.accountNumber = totalAccounts;
        this.balance = initialBalance;
    }

    // Autogenerated Getters and Setters:

    public static int getTotalAccounts() {
        return totalAccounts;
    }

    public static void setTotalAccounts(int totalAccounts) {
        BankAccount.totalAccounts = totalAccounts;
    }

    public int getAccountNumber() {
        return accountNumber;
    }

    public void setAccountNumber(int accountNumber) {
        this.accountNumber = accountNumber;
    }

    public double getBalance() {
        return balance;
    }

    public void setBalance(double balance) {
        this.balance = balance;
    }


    // Other Methods:

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
        } else {
            System.out.println("Deposite amount is invalid.");
        }
    }

    public void withdraw(double amount) {
        if (this.balance >= amount) {
            this.balance -= amount;
        } else {
            System.out.println("You do not have enough money or the amoutn is negative.");
        }
    }
}
